mapper.select:
SELECT conversation_id, user_id, title, revision, created_at, updated_at FROM chatbot_conversations WHERE user_id = #{userId} AND deleted_at IS NULL
AND conversation_id = #{conversationId}
ORDER BY updated_at DESC, conversation_id DESC

mapper.update:
UPDATE chatbot_conversations
SET title = CASE
WHEN revision = 0 THEN #{title}
ELSE title
END,
revision = revision + 1,
updated_at = UTC_TIMESTAMP(6) + INTERVAL 9 HOUR
WHERE conversation_id = #{conversationId}
AND user_id = #{userId}
AND revision = #{revision}
AND deleted_at IS NULL
